package main

import (
	"github.com/gin-gonic/gin"

	"ginapp/handlers"
	"ginapp/service"
)

func SetupRouter() *gin.Engine {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	svc := service.NewAccountService()
	handlers.RegisterAccountRoutes(r, svc)
	return r
}

func main() {
	SetupRouter().Run(":8080")
}

