package service

import "errors"

var ErrInsufficientFunds = errors.New("insufficient funds")
var ErrNotFound = errors.New("account not found")

type AccountService struct {
	balances map[string]int
}

func NewAccountService() *AccountService {
	return &AccountService{balances: map[string]int{"alice": 100}}
}

// Withdraw returns ErrNotFound for an unknown account, ErrInsufficientFunds
// when the balance is too low, or nil and the new balance on success.
func (s *AccountService) Withdraw(account string, amount int) (int, error) {
	balance, ok := s.balances[account]
	if !ok {
		return 0, ErrNotFound
	}
	if amount > balance {
		return 0, ErrInsufficientFunds
	}
	s.balances[account] = balance - amount
	return s.balances[account], nil
}

