package handlers

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"ginapp/service"
)

func RegisterAccountRoutes(r *gin.Engine, svc *service.AccountService) {
	r.POST("/withdraw", func(c *gin.Context) {
		var body struct {
			Account string `json:"account"`
			Amount  int    `json:"amount"`
		}
		c.ShouldBindJSON(&body)
		balance, err := svc.Withdraw(body.Account, body.Amount)
		if err != nil {
			// BUG: every service error is mapped to 500, so a missing account
			// and an overdraft both look like server errors.
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, gin.H{"balance": balance})
	})
}

