package main

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func withdraw(body string) (int, string) {
	r := SetupRouter()
	req := httptest.NewRequest("POST", "/withdraw", strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	return w.Code, w.Body.String()
}

func TestWithdrawStatusMapping(t *testing.T) {
	if code, body := withdraw(`{"account": "alice", "amount": 40}`); code != http.StatusOK {
		t.Fatalf("valid withdrawal: got %d, want 200 (%s)", code, body)
	}
	if code, _ := withdraw(`{"account": "ghost", "amount": 10}`); code != http.StatusNotFound {
		t.Fatalf("missing account: got %d, want 404", code)
	}
	if code, _ := withdraw(`{"account": "alice", "amount": 100000}`); code != http.StatusConflict {
		t.Fatalf("overdraft: got %d, want 409", code)
	}
}

